    dict(city="Delhi", start=14, region="Delhi", accent="#e2603a", motif="jaali", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Motichur_ka_laddu.JPG/500px-Motichur_ka_laddu.JPG", bg_alt="Motichoor ladoo, a Delhi sweet of fried gram-flour pearls", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Red-Fort,Delhi.JPG/500px-Red-Fort,Delhi.JPG", landmark_name="Red Fort", sweet="Ladoo", note="Besan, boondi, or motichoor, hand-rolled outside every Chandni Chowk mithai shop. The default sweet for good news.", song="Dilli Wali Girlfriend", video="4QzmXuOghtU", history="Delhi has served as the capital of several historical empires, from the Delhi Sultanate through the Mughals to British India. The Red Fort was the seat of Mughal power for over 200 years.", places=["Red Fort", "Qutub Minar", "India Gate", "Chandni Chowk"]),
