    dict(city="Varanasi", start=22, region="Varanasi, Uttar Pradesh", accent="#d1483f", motif="banarasi", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Malaiyo.jpg/500px-Malaiyo.jpg", bg_alt="Malaiyo, whipped milk-foam sweet from Varanasi's winter mornings", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Dashashwamedha_ghat_on_the_Ganga,_Varanasi.jpg/500px-Dashashwamedha_ghat_on_the_Ganga,_Varanasi.jpg", landmark_name="Dashashwamedh Ghat", sweet="Malaiyo", note="Whipped, dew-set milk foam sold only on winter mornings on the ghats. Dissolves before it fully lands on the tongue.", song="Banarasiya", video="-ydFM29TPnQ", history="One of the oldest continuously inhabited cities in the world, Varanasi (Kashi) has been a center of Hindu learning and pilgrimage on the Ganges for millennia.", places=["Dashashwamedh Ghat", "Kashi Vishwanath Temple", "Sarnath", "Manikarnika Ghat"]),
    dict(city="Amritsar", start=16, region="Amritsar, Punjab", accent="#c23e3e", motif="phulkari", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Pinni_cropped.JPG/500px-Pinni_cropped.JPG", bg_alt="Pinni, a Punjabi winter sweet of wheat, ghee and nuts", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Golden_Temple_reflecting_in_the_Sarovar,_Amritsar.jpg/500px-Golden_Temple_reflecting_in_the_Sarovar,_Amritsar.jpg", landmark_name="Golden Temple", sweet="Pinni", note="Whole wheat, ghee, and nuts rolled into a dense winter ladoo, packed into every tiffin a Punjabi son takes leaving home.", song="Laung Laachi", video="YpkJO_GrCo0", history="Founded in 1577 by the fourth Sikh Guru, Guru Ram Das, around a sacred pool. The Golden Temple built at its center makes Amritsar the spiritual home of Sikhism.", places=["Golden Temple", "Jallianwala Bagh", "Wagah Border", "Partition Museum"]),
    dict(city="Mysore", start=21, region="Mysore, Karnataka", accent="#f0ad3f", motif="mysoresilk", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Mysore_pak.jpg/500px-Mysore_pak.jpg", bg_alt="Mysore Pak, a ghee and gram-flour sweet from the Mysore Palace kitchen", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Mysore_Palace_Mysore.jpg/500px-Mysore_Palace_Mysore.jpg", landmark_name="Mysore Palace", sweet="Mysore Pak", note="Ghee, gram flour, and sugar, invented in the Mysore Palace kitchen in the 1930s and never bettered since.", song="Belageddu", video="ebz20FHrT44", history="Capital of the Kingdom of Mysore under the Wodeyar dynasty for centuries, the city is famed for its Dussehra celebrations and Indo-Saracenic architecture.", places=["Mysore Palace", "Chamundi Hills", "Brindavan Gardens", "St. Philomena's Church"]),
    dict(city="Hyderabad", start=11, region="Hyderabad, Telangana", accent="#e0577a", motif="bidri", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Double_Ka_Meetha.JPG/500px-Double_Ka_Meetha.JPG", bg_alt="Double Ka Meetha, a Hyderabadi bread pudding in saffron milk", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Charminar_Hyderabad_1.jpg/500px-Charminar_Hyderabad_1.jpg", landmark_name="Charminar", sweet="Double Ka Meetha", note="Fried bread soaked in saffron milk and topped with dry fruits, the Nizami answer to bread pudding.", song="Naatu Naatu", video="4_eEgJhsBMo", history="Founded in 1591 by Muhammad Quli Qutb Shah, Hyderabad later became the seat of the Nizams, among the wealthiest rulers in the world, blending Deccani, Persian, and Qutb Shahi influences.", places=["Charminar", "Golconda Fort", "Chowmahalla Palace", "Hussain Sagar"]),
    dict(city="Tirunelveli", start=4, region="Tirunelveli, Tamil Nadu", accent="#b3703f", motif="kolam", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/0/04/Tirunelveli_halwa.jpg/500px-Tirunelveli_halwa.jpg", bg_alt="Tirunelveli halwa, a wheat halwa first sold in the dark", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Tirunelveli_Nellaiappar_Temple_1.jpg/500px-Tirunelveli_Nellaiappar_Temple_1.jpg", landmark_name="Nellaiappar Temple", sweet="Iruttukadai Halwa", note="Wheat halwa first sold in the dark (\"iruttu\") because the shop had no electricity. The name outlived the blackout by a century.", song="Rowdy Baby", video="x6Q7c9RyMzk", history="One of the oldest cities in Tamil Nadu, sitting on the Thamirabarani river, taking its name from the Nellaiappar Temple.", places=["Nellaiappar Temple", "Courtallam Falls", "Manimuthar Falls", "Papanasam"]),
    dict(city="Patna", start=6, region="Patna, Bihar", accent="#c9702f", motif="madhubani", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/Thekuaa.jpg/500px-Thekuaa.jpg", bg_alt="Thekua, a wheat and jaggery sweet made for Chhath puja", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/d/d9/GOLGHAR_-_BRITSH_GRANARY.JPG/500px-GOLGHAR_-_BRITSH_GRANARY.JPG", landmark_name="Golghar", sweet="Thekua", note="Wheat and jaggery, deep-fried and stamped with a wooden mould. The sweet that travels in the Chhath prasad basket.", song="Kanch Hi Baans Ke Bahangiya", video="Vc8wNTgKG1k", history="Known in antiquity as Pataliputra, Patna was the capital of the Mauryan and Gupta empires, one of the largest cities in the ancient world under Chandragupta Maurya.", places=["Golghar", "Patna Sahib Gurudwara", "Buddha Smriti Park", "Bihar Museum"]),
    dict(city="Pune", start=3, region="Pune, Maharashtra", accent="#d99a2e", motif="warli", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Puneri_Ukadiche_Modak.jpg/500px-Puneri_Ukadiche_Modak.jpg", bg_alt="Ukadiche modak, a steamed rice-flour dumpling from Pune", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Shaniwar_Wada_Fort_Pune.jpg/500px-Shaniwar_Wada_Fort_Pune.jpg", landmark_name="Shaniwar Wada", sweet="Modak", note="Steamed rice-flour dumplings stuffed with jaggery and coconut. Ganpati Bappa's favourite, made fresh every Chaturthi.", song="Sukhkarta Dukhharta", video="2LoxjhZ8jRo", history="Rose to prominence as the seat of the Peshwas, prime ministers of the Maratha Empire, in the 18th century. Shaniwar Wada was their fortified residence.", places=["Shaniwar Wada", "Aga Khan Palace", "Sinhagad Fort", "Osho Ashram"]),
    dict(city="Raipur", start=10, region="Raipur, Chhattisgarh", accent="#b8562f", motif="bastar", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Khurmi,_Chhattisgarhi_Cuisine.jpg/500px-Khurmi,_Chhattisgarhi_Cuisine.jpg", bg_alt="Khurmi, a Chhattisgarhi wheat and jaggery sweet", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Mahant_Ghasidas_Sangrahalaya_Raipur_(5).jpg/500px-Mahant_Ghasidas_Sangrahalaya_Raipur_(5).jpg", landmark_name="Mahant Ghasidas Memorial Museum", sweet="Khurmi", note="Wheat flour, jaggery, and ghee, shaped into discs and deep-fried, made at home especially during the Pola and Teej festivals.", song="Arpa Pairi Ke Dhar", video="BKPhrjBheAA", history="Founded by Brahma Deo Rai of the Kalachuri dynasty, which ruled the region historically known as Dakshina Kosala. Raipur became the capital of Chhattisgarh when the state was carved out of Madhya Pradesh on November 1, 2000.", places=["Mahant Ghasidas Memorial Museum", "Swami Vivekananda Sarovar (Budha Talab)", "Purkhouti Muktangan, Naya Raipur"]),
    dict(city="Surat", start=9, region="Surat, Gujarat", accent="#e8973f", motif="zari", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Surti_Ghari.jpg/500px-Surti_Ghari.jpg", bg_alt="Ghari, a layered Surti sweet of mawa, ghee, and dry fruits", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Surat_Fort,_front_View.jpg/500px-Surat_Fort,_front_View.jpg", landmark_name="Surat Fort", sweet="Ghari", note="A rich, layered sweet of mawa, ghee, and dry fruits set on a crisp base, traditionally eaten in Surat on Chandni Padvo, the full-moon night after Diwali.", song="Vaishnav Jan To", video="oyM_PZQvy14", history="One of the busiest ports on the Indian Ocean trade route through the Mughal era, Surat became the site of the British East India Company's first Indian trading factory in 1608. It later grew into a major center for textiles and diamond polishing, earning it the names \"Silk City\" and \"Diamond City.\"", places=["Surat Fort (Old Fort)", "Dutch Garden", "Sardar Vallabhbhai Patel Museum"]),
    dict(city="Kozhikode", start=7, region="Kozhikode, Kerala", accent="#3f9e6d", motif="keralamural", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/Calicut_Halwa.jpg/500px-Calicut_Halwa.jpg", bg_alt="Calicut halwa, a soft chewy sweet sold on Kozhikode's Sweet Meat Street", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Kappad_4.jpg/500px-Kappad_4.jpg", landmark_name="Kappad Beach", sweet="Kozhikodan Halwa", note="A soft, chewy, jelly-like halwa of wheat or rice starch, ghee, sugar, and cashews, famously sold along Kozhikode's \"Sweet Meat Street\" in black, white, and red varieties.", song="Omanathinkal Kidavo", video="K96EMPiTw6U", history="Kozhikode (Calicut) was the seat of the powerful Zamorin dynasty and a key node in the Indian Ocean spice trade for centuries. In 1498, Vasco da Gama landed at nearby Kappad beach, opening the first direct sea route between Europe and India.", places=["Kappad Beach", "Kozhikode Beach", "Beypore (traditional Uru boat-building port)"]),
    dict(city="Puri", start=5, region="Puri, Odisha", accent="#d1893f", motif="pattachitra", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Khaja_from_Puri,_Odisha.jpg/500px-Khaja_from_Puri,_Odisha.jpg", bg_alt="Khaja, a crisp flaky fried pastry offered as prasad in Puri", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Jagannath_Temple,_Puri_04.jpg/500px-Jagannath_Temple,_Puri_04.jpg", landmark_name="Jagannath Temple", sweet="Khaja", note="A crisp, flaky, multi-layered fried pastry dipped in sugar syrup, one of the traditional sweets offered as prasad at the Jagannath Temple.", song="Bande Utkala Janani", video="XNrRKER33DY", history="Puri is one of Hinduism's Char Dham pilgrimage sites, home to the Jagannath Temple built in the 12th century under the Eastern Ganga dynasty. It hosts the annual Rath Yatra chariot festival, one of the largest religious processions in the world.", places=["Jagannath Temple", "Puri Beach", "Konark Sun Temple (nearby)"]),
    dict(city="Almora", start=8, region="Almora, Uttarakhand", accent="#6b8f4a", motif="aipan", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Bal_mithai.jpg/500px-Bal_mithai.jpg", bg_alt="Bal Mithai, a dark khoya fudge rolled in sugar-coated poppy-seed balls", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Kasar_Devi_Temple.JPG/500px-Kasar_Devi_Temple.JPG", landmark_name="Kasar Devi Temple", sweet="Bal Mithai", note="Khoya cooked with cane sugar until deep brown, cut into cubes and rolled in tiny sugar-coated poppy-seed balls, a specialty of Kumaon's Almora district.", song="Bedu Pako Baro Masa", video="SAQe0L7RP30", history="Founded in 1568 by Kalyan Chand of the Chand dynasty, Almora was the seat of the Kumaon kingdom into the late 18th century, later held by Gorkha forces until the British took it in the 1814 Anglo-Gorkha War. Set on a Himalayan ridge, it remains the cultural capital of Kumaon.", places=["Kasar Devi Temple", "Bright End Corner", "Binsar Wildlife Sanctuary"]),
    dict(city="Panaji", start=17, region="Panaji, Goa", accent="#2f9ea8", motif="azulejo", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Home_Made_Bebinca_from_Goa_India.jpg/500px-Home_Made_Bebinca_from_Goa_India.jpg", bg_alt="A home-made Goan bebinca with a slice cut to show its layers", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Front_Elevation_of_Basilica_of_Bom_Jesus.jpg/500px-Front_Elevation_of_Basilica_of_Bom_Jesus.jpg", landmark_name="Basilica of Bom Jesus", sweet="Bebinca", note="A 7-to-16-layer Indo-Portuguese cake of flour, sugar, ghee, coconut milk, and egg yolk, baked one thin layer at a time and traditionally made for Christmas.", song="Bebdo", video="q1w95jUCHDU", history="Panaji appears in an 1059 CE Kadamba-dynasty copper plate; its fort was stormed by the Portuguese in 1510. After an epidemic devastated Old Goa, the Portuguese rebuilt around Panaji as the new capital of Portuguese India in the 18th century, and it has been Goa's state capital since 1987.", places=["Basilica of Bom Jesus (Old Goa)", "Fort Aguada", "Miramar Beach"]),
    dict(city="Srinagar", start=19, region="Srinagar, Jammu & Kashmir", accent="#4a7fa8", motif="paisley", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Firni_Or_Phirni.jpg/500px-Firni_Or_Phirni.jpg", bg_alt="Firni, a rose-water scented ground-rice pudding from Kashmir", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/c/c0/Dal_Lake,_Srinagar,_July_2012.jpg/500px-Dal_Lake,_Srinagar,_July_2012.jpg", landmark_name="Dal Lake", sweet="Firni", note="A ground-rice milk pudding flavoured with rose water or kewra, known locally as \"firin,\" the traditional closing dessert of Kashmir's Wazwan feast.", song="Bumbro", video="PquZBLuFmwA", history="Present-day Srinagar traces to Parvarapura, founded in the 6th century by King Pravarasena II at the base of Hari Parbat. Sultanate rulers built the Jamia Masjid in 1402, and Mughal emperors later laid out the Shalimar and Nishat gardens along the lake.", places=["Dal Lake", "Shalimar Bagh", "Shankaracharya Temple"]),
    dict(city="Puducherry", start=14, region="Puducherry", accent="#a85f8f", motif="frenchgrille", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Cr%C3%A8me_br%C3%BBl%C3%A9e_w._whipped_cream.jpg/500px-Cr%C3%A8me_br%C3%BBl%C3%A9e_w._whipped_cream.jpg", bg_alt="Crème brûlée, a legacy of Puducherry's French colonial past", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/The_Matrimandir_in_Auroville,_Tamil_Nadu,_India.jpg/500px-The_Matrimandir_in_Auroville,_Tamil_Nadu,_India.jpg", landmark_name="Matrimandir, Auroville", sweet="Crème Brûlée", note="A caramelized-sugar custard that stuck around after 280 years as a French colonial outpost. No other Indian city's \"local sweet\" is French, and that's exactly the point.", song="Kakkai Chiraginile", video="bXZOcjqCY-8", history="Ruled by the Pallavas, Cholas, and Pandyas before French trader François Martin founded a settlement in 1674, Puducherry stayed France's chief Indian colony until administration passed to India in 1954. Poet-freedom fighter Subramania Bharati lived here in exile from 1908 to 1918.", places=["Auroville (Matrimandir)", "Sri Aurobindo Ashram", "Promenade Beach / French Quarter"]),
    dict(city="Imphal", start=16, region="Imphal, Manipur", accent="#5a9e7a", motif="phanek", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Chahao_kheer.jpg/500px-Chahao_kheer.jpg", bg_alt="Chak-hao kheer, a pudding made from Manipur's black rice", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Kangla_Fort,_imphal.JPG/500px-Kangla_Fort,_imphal.JPG", landmark_name="Kangla Fort", sweet="Chak-hao Kheer", note="A rice pudding made from Manipur's aromatic, dark-purple chak-hao rice, cooked with milk, coconut, and raisins for festivals and special occasions.", song="Khongjom Parva (Moirang Kangleirol)", video="KRC_9PkAQRs", history="Imphal was the seat of the Meitei Ningthouja dynasty kings for centuries, centered on Kangla Fort, until the British took control after the 1891 Anglo-Manipur War. In 1944 it was the site of the Battle of Imphal, where Allied forces halted Japan's attempted invasion of India.", places=["Kangla Fort", "Loktak Lake", "Ima Keithel (the all-women's market)"]),
    dict(city="Guwahati", start=14, region="Guwahati, Assam", accent="#4a9e8f", motif="gamosa", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Til_Pitha.jpg/500px-Til_Pitha.jpg", bg_alt="Til Pitha, a rice-flour crepe rolled around sesame and jaggery", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Kamakhya_Temple,_Guwahati.jpg/500px-Kamakhya_Temple,_Guwahati.jpg", landmark_name="Kamakhya Temple", sweet="Til Pitha", note="A rice-flour crepe rolled around roasted sesame and jaggery, made especially during Assam's Magh Bihu harvest festival.", song="Mayabini Ratir Bukut", video="AqUonMjxaog", history="Guwahati, on the banks of the Brahmaputra, was known in antiquity as Pragjyotishpura and served as capital of the ancient Kamarupa kingdom. It is today Assam's largest city and the gateway to Northeast India, home to the Kamakhya Temple, one of the subcontinent's oldest Shakti Peetha shrines.", places=["Kamakhya Temple", "Umananda Island", "Assam State Museum"]),
    dict(city="Tirupati", start=5, region="Tirupati, Andhra Pradesh", accent="#d94f5f", motif="kalamkari", bg="https://upload.wikimedia.org/wikipedia/commons/thumb/1/18/A_Tirupathi_laddu.jpg/500px-A_Tirupathi_laddu.jpg", bg_alt="Tirupati laddu, a ghee-roasted gram-flour laddu offered as temple prasadam", landmark_img="https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/A_View_of_Tirumala_Venkateswara_Temple.JPG/500px-A_View_of_Tirumala_Venkateswara_Temple.JPG", landmark_name="Tirumala Venkateswara Temple", sweet="Tirupati Laddu", note="A ghee-roasted gram-flour laddu with cashews, cardamom, and raisins, prepared daily as prasadam at the Tirumala temple and awarded a Geographical Indication tag in 2009.", song="Sri Venkatesa Suprabhatam", video="R-bwYbOExt8", history="Tirupati grew around the Tirumala Venkateswara Temple, one of the world's most-visited religious sites, with inscriptions and endowments dating to the Pallava, Chola, and Vijayanagara periods.", places=["Tirumala Venkateswara Temple", "Sri Venkateswara Zoological Park", "Kapila Theertham"]),
